const LOCKFILES = ["package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml", "bun.lockb", "bun.lock"];
const MANAGERS = { "package-lock.json": "npm", "npm-shrinkwrap.json": "npm", "yarn.lock": "yarn", "pnpm-lock.yaml": "pnpm", "bun.lockb": "bun", "bun.lock": "bun" };
function fileSet(context) { return new Set(context.files.map((file) => file.relPath)); }
function packageManagerMismatch(packageManager, locks) { const [manager] = packageManager.split("@"); return locks.some((lock) => MANAGERS[lock] !== manager); }
export const dependenciesRule = { id: "dependencies", category: "dependencies", description: "Checks deterministic package-manager and lockfile consistency.", run(context) { const paths = fileSet(context); const findings = []; const packageJson = context.files.find((file) => file.relPath === "package.json"); if (!packageJson) return findings; const locks = LOCKFILES.filter((file) => paths.has(file)); if (locks.length === 0) { findings.push({ id: "dependencies.missing-lockfile", rule: "missing-lockfile", category: "dependencies", severity: "low", message: "package.json exists without a lockfile.", path: "package.json", fixable: false, confidence: "medium", remediation: "Commit the lockfile used by the project when reproducible installs are expected." }); } if (locks.length > 1) { findings.push({ id: "dependencies.multiple-lockfiles", rule: "multiple-lockfiles", category: "dependencies", severity: "medium", message: `Multiple package-manager lockfiles are present: ${locks.join(", ")}.`, fixable: false, confidence: "high", remediation: "Keep one authoritative package manager unless multiple lockfiles are intentionally maintained." }); } if (packageJson.isText && packageJson.content) { try { const parsed = JSON.parse(packageJson.content); if (typeof parsed.packageManager === "string" && locks.length > 0 && packageManagerMismatch(parsed.packageManager, locks)) { findings.push({ id: "dependencies.package-manager-mismatch", rule: "package-manager-mismatch", category: "dependencies", severity: "medium", message: `packageManager declares ${parsed.packageManager}, but the lockfile set suggests a different manager.`, path: "package.json", fixable: false, confidence: "high", remediation: "Align packageManager metadata and the committed lockfile." }); } } catch { findings.push({ id: "dependencies.invalid-package-json", rule: "invalid-package-json", category: "dependencies", severity: "high", message: "package.json is not valid JSON.", path: "package.json", fixable: false, confidence: "high", remediation: "Repair package.json before relying on package-manager tooling." }); } } return findings; } };
